    'doc.builtin.rapport.body': '# {{datamangd}}\n\n*Skýrsla búin til {{datum}} með {{app}}.*\n\n{{#beskrivning}}{{beskrivning}}\n\n{{/beskrivning}}Gagnasafnið inniheldur **{{antal_rader}} raðir** og **{{antal_kolumner}} dálka**.{{#kalla}} Uppruni: {{kalla}}.{{/kalla}}\n\n## Dálkar\n\n{{#tabell}}kalla: kolumner; rubrik: Dálkar í gagnasafninu{{/tabell}}\n\n## Fyrstu raðirnar\n\n{{#tabell}}topp: 20; rubrik: Fyrstu 20 raðirnar{{/tabell}}\n\n## Myndrit\n\nSettu inn vistað myndrit með merkinu diagram og heiti myndritsins í gæsalöppum, sjá hjálpina til hægri. Fjarlægðu þessa málsgrein þegar þú ert búin(n).\n',
