    'course.open': 'Opna grunnnámskeiðið',
    'course.open.hint': 'Gagnvirk yfirferð yfir alla hami með sýnigögnum',
    'course.offer': 'Nýtt: Grunnnámskeiðið sýnir allt forritið skref fyrir skref með sýnigögnum.',
    'course.process.column': 'thusundir',
    'course.viz.chart': 'Mannfjöldi eftir lénum 2024',
    'course.welcome.title': 'Velkomin í Dataspatium',
    'course.welcome.p1': 'Dataspatium sækir, vinnur, greinir, myndgerir og flytur út gögn alfarið í vafranum. Ekkert er sett upp og gögnin þín fara ekki af tölvunni nema þegar þú sækir gögn úr vefþjónustu.',
    'course.welcome.p2': 'Grunnnámskeiðið tekur um tíu mínútur. Þú fylgir raunverulegu dæmi, {example}, gegnum átta hami forritsins: {modes}. Í hverju skrefi getur þú leyst verkefnið eða látið námskeiðið gera það fyrir þig.',
    'course.welcome.p3': 'Skjárinn er eins í öllum hömum: hamirnir efst, hlutaspjaldið til vinstri, vinnusvæðið í miðjunni, eiginleikarnir til hægri og dagbókin neðst. Hægt er að lágmarka námskeiðið og opna það aftur úr hjálpinni.',
    'course.import.title': 'Sækja: sækja gögn',
    'course.import.p1': 'Öll gögn í forritinu eru í gagnasöfnum: töflum með nefndum dálkum þar sem hver dálkur hefur gerð eins og texta, heiltölu, tölu eða dagsetningu. Gögn má sækja úr skrám (CSV, Excel, JSON, Parquet, SPSS og fleiri), límdum texta, vefslóðum og opnum vefþjónustum stofnana á öllum Norðurlöndum.',
    'course.import.task': 'Farðu í {mode} og smelltu á {button}. Þá verður gagnasafnið {name} til.',
    'course.import.done': 'Gagnasafnið er tilbúið: 290 sænsk sveitarfélög með dálkunum kommunkod (sveitarfélagskóði), kommun (sveitarfélag), lanskod (lénskóði), lan (lén), ar (ár) og folkmangd (mannfjöldi). Stutta heitið er {short}.',
    'course.manage.title': 'Umsjón: gagnasöfn og vinnusvæðið',
    'course.manage.p1': 'Hvert gagnasafn hefur heiti og stutt heiti. Stutta heitið, hér {short}, hefur aðeins lágstafi, tölustafi og undirstrik og er notað í SQL og R. Í {mode} sérðu heimildina, stærðina, dálkana með gerðum og lýsingum og útgáfur sem þú getur farið aftur í.',
    'course.manage.p2': 'Allt vistast sjálfkrafa í vafranum. Taktu öðru hverju afrit af vinnusvæðinu með {backup} svo að ekkert glatist ef gögnum vafrans er eytt.',
    'course.manage.task': 'Opnaðu {mode}, veldu gagnasafnið á hlutaspjaldinu og skoðaðu upplýsingarnar og dálkana.',
    'course.manage.done': 'Hér getur þú líka breytt heiti og stuttu heiti, deilt gagnasöfnum sem pökkum og eytt þeim.',
    'course.process.title': 'Vinna: hreinsa og reikna',
    'course.process.p1': 'Í {mode} sérðu alla töfluna. Smelltu á dálkfyrirsögn til að raða og sjá snið dálksins með gildum sem vantar, einstökum gildum og dreifingu. Leiðréttu gildi beint í reitunum eða með aðgerðum.',
    'course.process.p2': 'Hver breyting verður skref í {recipe} gagnasafnsins. Skrefin má afturkalla, keyra aftur á nýrri útgáfu gagnanna og afrita sem R- eða SQL-kóða.',
    'course.process.task': 'Búðu til dálk með mannfjöldanum í þúsundum: {mode} → {actions} → {group} → {op}. Sláðu inn heitið {column} og segðina {expression}.',
    'course.process.done': 'Dálkurinn {column} er nú síðastur í töflunni og skrefið er í uppskriftinni.',
    'course.sql.title': 'Greina: spyrja með SQL',
    'course.sql.p1': '{mode} er hamurinn fyrir kóða og tölfræði. Í SQL-flipanum heitir valda gagnasafnið {data}, en öll gagnasöfn má líka nálgast með stuttu heitunum sínum. Þess vegna getur ein fyrirspurn tengt saman mörg gagnasöfn.',
    'course.sql.task': 'Opnaðu {mode} → {tab}, skrifaðu fyrirspurnina hér fyrir neðan og smelltu á {run}. Fyrirspurnin leggur saman mannfjöldann eftir lénum.',
    'course.sql.done': 'Stokkhólmslén er stærst með nærri 2,5 milljónir íbúa og á eftir koma Vestra-Gautland og Skánn. Með {save} verður niðurstaðan nýtt gagnasafn.',
    'course.r.title': 'Greina: reikna með R',
    'course.r.p1': 'R-flipinn keyrir R beint í vafranum með pökkum eins og dplyr og ggplot2. {read} les gagnasafn sem data frame og {write} vistar data frame sem nýtt gagnasafn. Í fyrsta skipti tekur nokkrar sekúndur að ræsa R.',
    'course.r.task': 'Opnaðu {mode} → {tab}, skrifaðu kóðann hér fyrir neðan og smelltu á {run}. Kóðinn tekur saman mannfjöldann og teiknar stuðlarit.',
    'course.r.done': 'Miðgildið er rúmlega 16.000 íbúar: helmingur sveitarfélaganna er minni en það og það stærsta, Stokkhólmur, hefur nærri milljón íbúa. Þess vegna er lograkvarði á myndritinu.',
    'course.viz.title': 'Myndgera: búa til myndrit',
    'course.viz.p1': 'Myndrit eru búin til með myndritasmiðnum (Vega-Lite), tilbúnum D3-sniðum eða R. Þau nota öll liti og letur forritsins, eru teiknuð upp á nýtt þegar gögnin breytast og má safna saman í mælaborð með sameiginlegum síum.',
    'course.viz.task': 'Opnaðu {mode} → {new} → {builder}. Veldu {type}, stilltu {x} á lan ({y} er þegar folkmangd) og smelltu á {save}.',
    'course.viz.done': 'Myndritið er vistað. Prófaðu líka myndritagerðina {map} ásamt sýnigagnasafninu {boundaries} til að sýna mannfjöldann á korti.',
    'course.export.title': 'Flytja út: deila niðurstöðunni',
    'course.export.p1': 'Í {mode} vistar þú gögn sem CSV, Excel, JSON, Parquet, SQLite, SPSS og fleiri snið, myndrit sem PNG, SVG, PDF eða PowerPoint og skjöl úr skjalasniðum sem Word, PDF, HTML eða LaTeX, jafnvel eitt skjal fyrir hvern hóp í einni keyrslu.',
    'course.export.task': 'Opnaðu {mode}, veldu til dæmis Excel-sniðið og smelltu á {run}.',
    'course.export.done': 'Skráin lendir meðal niðurhalaðra skráa vafrans. Fliparnir {charts} og {documents} virka eins fyrir myndrit og skjöl.',
    'course.finish.title': 'Lokið: svona heldurðu áfram',
    'course.finish.p1': 'Þú hefur farið í gegnum alla keðjuna: sækja, hafa umsjón, vinna, greina, myndgera og flytja út.',
    'course.finish.p2': 'Haltu áfram með eigin gögn: slepptu skrá í {import}, veldu lönd og sæktu úr opinni vefþjónustu, skrifaðu minnisbækur með texta, R og SQL í {analyse} eða búðu til skjalasnið í {export}. Alt+1–6 skiptir um ham og {palette} opnar skipanaspjaldið.',
    'course.finish.p3': 'Námskeiðið er áfram aðgengilegt undir {help} og á skipanaspjaldinu.',
